steps.script:
var bad = []
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) != 1 or int(u.get("status", 0)) != GameStateData.UnitStatus.DEPLOYED:
		continue
	var f = u.get("flags", {})
	if not (f.get("moved", false) and f.get("remained_stationary", false)):
		bad.append(uid)
return bad.size()

var touched = 0
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 2 and u.get("flags", {}).get("remained_stationary", false):
		touched += 1
return touched
